engine.auvListUsageFiles:
function auvListUsageFiles() {
  var owner = "apndrewn";
  var repo  = "eli-data";
  var url = "https://api.github.com/repos/" + owner + "/" + repo +
    "/contents/usage?t=" + Date.now();
  return fetch(url, {
    cache: "no-store",
    headers: { "Accept": "application/vnd.github+json" },
  }).then(function (r) {
    if (r.status === 404) return [];
    if (!r.ok) throw new Error("list failed: HTTP " + r.status);
    return r.json();
  }).then(function (arr) {
    if (!Array.isArray(arr)) return [];
    return arr.filter(function (e) {
      return e && e.type === "file" && /\.json$/i.test(String(e.name || ""));
    }).map(function (e) {
      return { name: e.name, download_url: e.download_url };
    });
  });
}

// Fetch + parse a single usage JSON. Returns the digest object or null on
// failure. Caller is expected to feed download_url straight in.

engine.auvFetchDigest:
function auvFetchDigest(downloadUrl) {
  if (!downloadUrl) return Promise.resolve(null);
  // Cache-bust to defeat browser cache; GitHub raw URLs include a SHA-ish
  // refspec but the URL is unique-per-commit so this is belt-and-suspenders.
  var url = downloadUrl + (downloadUrl.indexOf("?") === -1 ? "?" : "&") + "_t=" + Date.now();
  return fetch(url, { cache: "no-store" }).then(function (r) {
    if (!r.ok) return null;
    return r.json();
  }).then(function (j) {
    if (!j || !Array.isArray(j.days)) return null;
    return j;
  }).catch(function () { return null; });
}

// Aggregate a list of digests into the shape the dashboard renders.
// Returns:
//   {
//     users: [{ userKey, userName, sessions, activeDays, lastPushAt, days }],
//     tools: [{ tool, launches }],            // sorted desc
//     daily: [{ date, sessions }],            // sorted asc, last 7 days only
//     grid:  { dates:[YYYY-MM-DD,...], users:[{userKey,userName,cells:{date:{sessions,topTool}}}] },
//   }

engine.auvAggregate:
function auvAggregate(digests) {
  digests = Array.isArray(digests) ? digests.filter(Boolean) : [];
  var users = [];
  var toolTotals = {};
  var dailyTotals = {};        // date -> sessions
  var dailyCostTotals = {};    // date -> $ across all users
  var dateSet = {};
  var grandTotalCost = 0;
  digests.forEach(function (d) {
    var key = d.userKey || "unknown";
    var name = d.userName || key;
    var days = Array.isArray(d.days) ? d.days : [];
    var sessions = 0;
    var activeDays = 0;
    var lastPushAt = 0;
    // 2026-05-18 v27: aggregate per-user token cost + call count so
    // the viewer can surface AI spend, not just session counts.
    var userCost = 0;
    var userCalls = 0;
    var userPromptTokens = 0;
    var userCandidatesTokens = 0;
    days.forEach(function (day) {
      if (!day || !day.date) return;
      dateSet[day.date] = true;
      var tu = day.toolsUsed || {};
      var dayLaunches = 0;
      Object.keys(tu).forEach(function (t) {
        var c = Number(tu[t]) || 0;
        toolTotals[t] = (toolTotals[t] || 0) + c;
        dayLaunches += c;
      });
      // 2026-05-18 v28: "sessions" was always 0 in practice (the boot
      // debounce reset on every bundle re-eval). Replaced with total
      // tool launches for this day — more meaningful as an activity
      // signal. Daily/user totals all reflect launches now.
      sessions += dayLaunches;
      if (dayLaunches > 0) activeDays += 1;
      dailyTotals[day.date] = (dailyTotals[day.date] || 0) + dayLaunches;
      if (Number(day.lastActiveAt || 0) > lastPushAt) lastPushAt = Number(day.lastActiveAt);
      var dayCost = Number(day.estCostUSD || 0) || 0;
      userCost += dayCost;
      dailyCostTotals[day.date] = (dailyCostTotals[day.date] || 0) + dayCost;
      var tokens = day.tokens || {};
      Object.keys(tokens).forEach(function (model) {
        var bucket = tokens[model] || {};
        userCalls += Number(bucket.calls || 0);
        userPromptTokens += Number(bucket.promptTokens || 0);
        userCandidatesTokens += Number(bucket.candidatesTokens || 0);
      });
    });
    grandTotalCost += userCost;
    var gen = d.generatedAt ? Date.parse(d.generatedAt) : 0;
    if (gen && gen > lastPushAt) lastPushAt = gen;
    users.push({
      userKey: key,
      userName: name,
      // 2026-05-23 (Phase 2): pass fleet.userId through so the viewer
      // can resolve initials → full name via the identity lookup table.
      // Falls back to null when digest pre-dates the fleet block.
      userId: (d.fleet && d.fleet.userId) || null,
      sessions: sessions,
      activeDays: activeDays,
      lastPushAt: lastPushAt,
      days: days,
      costUSD: userCost,
      aiCalls: userCalls,
      promptTokens: userPromptTokens,
      candidatesTokens: userCandidatesTokens,
    });
  });
  // Most-active users — sort by sessions desc, then by activeDays desc.
  users.sort(function (a, b) {
    if (b.sessions !== a.sessions) return b.sessions - a.sessions;
    return b.activeDays - a.activeDays;
  });
  // Most-used tools — flatten + sort.
  var tools = Object.keys(toolTotals).map(function (t) {
    return { tool: t, launches: toolTotals[t] };
  }).sort(function (a, b) { return b.launches - a.launches; });
  // Daily series — last 7 days (descending then sliced then re-sorted asc).
  var sortedDates = Object.keys(dailyTotals).sort();
  var last7 = sortedDates.slice(-7);
  var daily = last7.map(function (date) {
    return {
      date: date,
      sessions: dailyTotals[date] || 0,
      costUSD: dailyCostTotals[date] || 0,
    };
  });
  // Grid — same date columns as daily, per user. 2026-05-18 v29:
  // cells now expose `launches` (sum of toolsUsed values) AND keep
  // the legacy `sessions` field as a synonym for backward compat
  // with the view's emptiness check. day.sessions in the raw data
  // has always been 0 because the per-boot debounce reset on every
  // bundle re-eval — using launches gives the cell real signal.
  var grid = {
    dates: last7.slice(),
    users: users.map(function (u) {
      var cells = {};
      (u.days || []).forEach(function (day) {
        if (!day || !day.date) return;
        if (last7.indexOf(day.date) === -1) return;
        var topTool = "";
        var topCount = 0;
        var launches = 0;
        var tu = day.toolsUsed || {};
        Object.keys(tu).forEach(function (t) {
          var c = Number(tu[t]) || 0;
          launches += c;
          if (c > topCount) { topCount = c; topTool = t; }
        });
        cells[day.date] = {
          launches: launches,
          sessions: launches, // backward-compat alias for the view
          topTool: topTool,
          topCount: topCount,
        };
      });
      return { userKey: u.userKey, userName: u.userName, userId: u.userId || null, cells: cells };
    }),
  };
  return {
    users: users,
    tools: tools,
    daily: daily,
    grid: grid,
    totalCostUSD: grandTotalCost,
  };
}

// Build a CSV string from the raw digest list. Columns: user,date,tool,launches.
// One row per (user, date, tool). Sessions emitted as a synthetic
// tool=__session row so the CSV is self-contained.

engine.auvBuildCsv:
function auvBuildCsv(digests) {
  var rows = [["user", "date", "tool", "launches"]];
  function _esc(v) {
    var s = String(v == null ? "" : v);
    if (/[",\r\n]/.test(s)) return '"' + s.replace(/"/g, '""') + '"';
    return s;
  }
  (Array.isArray(digests) ? digests : []).forEach(function (d) {
    var name = d.userName || d.userKey || "unknown";
    var days = Array.isArray(d.days) ? d.days : [];
    days.forEach(function (day) {
      if (!day || !day.date) return;
      var tu = day.toolsUsed || {};
      Object.keys(tu).forEach(function (t) {
        rows.push([name, day.date, t, Number(tu[t]) || 0]);
      });
      if (Number(day.sessions || 0) > 0) {
        rows.push([name, day.date, "__session", Number(day.sessions) || 0]);
      }
    });
  });
  return rows.map(function (r) { return r.map(_esc).join(","); }).join("\r\n");
}

view.renderDashboard:
function renderDashboard(opts) {
  var host = opts && opts.host;
  var data = (opts && opts.data) || { users: [], tools: [], daily: [], grid: { dates: [], users: [] } };
  var onRefresh = opts && opts.onRefresh;
  var onExport  = opts && opts.onExport;
  var totalDigests = (opts && opts.totalDigests) || 0;
  var cachedAt = (opts && opts.cachedAt) || 0;
  // 2026-05-23 (Phase 2): name-resolution wiring. resolveName is a
  // (userKey, userId) → displayName | null function provided by init.js
  // (admin_fleet lookup). showResolvedNames toggles whether to apply it.
  // hasLookup gates the toggle button (hide when admin hasn't loaded
  // admin_fleet yet — no lookup available, nothing to toggle).
  var resolveName = opts && opts.resolveName;
  var showResolvedNames = opts && opts.showResolvedNames;
  var hasLookup = opts && opts.hasLookup;
  var onToggleNames = opts && opts.onToggleNames;
  var lookupError = (opts && opts.lookupError) || "";
  function _userLabel(u) {
    if (!u) return "";
    if (showResolvedNames && resolveName) {
      var resolved = resolveName(u.userKey, u.userId);
      if (resolved) return resolved;
    }
    return u.userName || u.userKey || "—";
  }
  if (!host) return;

  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }
  function _fmtTool(t) {
    // ask_eli -> Ask Eli, admin_library_publisher -> Admin Library Publisher
    return String(t || "").split("_").map(function (p) {
      return p ? p.charAt(0).toUpperCase() + p.slice(1) : "";
    }).join(" ");
  }
  function _fmtDateShort(iso) {
    if (!iso) return "—";
    // "2026-05-13" → "May 13"
    var parts = String(iso).split("-");
    if (parts.length !== 3) return iso;
    var monthNames = ["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];
    var m = Number(parts[1]) - 1;
    var d = Number(parts[2]);
    if (m < 0 || m > 11 || !d) return iso;
    return monthNames[m] + " " + d;
  }
  function _fmtAgo(ms) {
    if (!ms) return "never";
    var sec = Math.max(0, Math.floor((Date.now() - ms) / 1000));
    if (sec < 60) return sec + "s ago";
    if (sec < 3600) return Math.floor(sec / 60) + "m ago";
    if (sec < 86400) return Math.floor(sec / 3600) + "h ago";
    return Math.floor(sec / 86400) + "d ago";
  }
  function _isStale(lastPushAt) {
    if (!lastPushAt) return true;
    return (Date.now() - lastPushAt) > (3 * 24 * 60 * 60 * 1000);
  }

  // Bar-width as % of maximum in a list. Returns 0..100 (capped).
  function _barPct(value, max) {
    if (!max || max <= 0) return 0;
    var pct = (Number(value) / Number(max)) * 100;
    if (pct < 1 && value > 0) pct = 1; // ensure visible
    if (pct > 100) pct = 100;
    return pct;
  }

  var maxUserSessions = (data.users[0] && data.users[0].sessions) || 0;
  var maxToolLaunches = (data.tools[0] && data.tools[0].launches) || 0;
  var maxDaily = data.daily.reduce(function (a, d) {
    return Math.max(a, d.sessions || 0);
  }, 0);

  // ─── Build HTML ────────────────────────────────────────────────────
  var html = '';
  html += '<div class="_auv_root">';

  // Header bar — 2026-05-18 v28: grand-total cost removed per request.
  html += '<div class="_auv_header">';
  html +=   '<div>';
  html +=     '<div class="_auv_header_eyebrow">ADMIN — RESTRICTED</div>';
  html +=     '<div class="_auv_header_title">📊 Usage Dashboard</div>';
  html +=     '<div class="_auv_header_sub">' + totalDigests + ' user' + (totalDigests === 1 ? '' : 's') +
              ' · cache ' + _fmtAgo(cachedAt) + '</div>';
  html +=   '</div>';
  html +=   '<div class="_auv_header_btns">';
  // 2026-05-23 (Phase 2): name-resolution toggle. Only renders when an
  // identity lookup is available (i.e. admin has opened admin_fleet at
  // least once this session, populating window._eli3_admin_fleet_lookup).
  if (hasLookup) {
    html +=   '<button class="_auv_btn _auv_btn_platinum" id="auvToggleNames" title="Toggle between initials and full names (from admin_fleet identity lookup)">' +
                (showResolvedNames ? '🆔 Show initials' : '👤 Show names') +
              '</button>';
  } else {
    var disabledHint = lookupError
      ? lookupError
      : "Set eli_admin_password + eli_user_github_pat (Settings → Credentials), then Refresh.";
    html +=   '<button class="_auv_btn _auv_btn_platinum" id="auvToggleNames" disabled title="' + _esc(disabledHint) + '">👤 Show names (' + _esc(lookupError || "lookup unavailable") + ')</button>';
  }
  html +=     '<button class="_auv_btn _auv_btn_platinum" id="auvRefresh">↻ Refresh</button>';
  html +=     '<button class="_auv_btn _auv_btn_platinum" id="auvExport">⬇ Export CSV</button>';
  html +=   '</div>';
  html += '</div>';

  if (!totalDigests) {
    html += '<div class="_auv_empty">' +
      'No usage files found yet. ' +
      'Either no users have pushed, or the eli_telemetry tool is not installed for them.' +
      '</div>';
    html += '</div>'; // _auv_root
    host.innerHTML = html;
    var refreshEl0 = host.querySelector("#auvRefresh");
    if (refreshEl0 && onRefresh) refreshEl0.onclick = onRefresh;
    return;
  }

  // Panel 1: Most active users
  html += '<div class="_auv_card">';
  html +=   '<div class="_auv_card_head"><span class="_auv_card_title">🥇 Most Active Users</span></div>';
  html +=   '<div class="_auv_card_body">';
  if (!data.users.length) {
    html += '<div class="_auv_empty_inner">No active users yet.</div>';
  } else {
    html += '<div class="_auv_list">';
    data.users.forEach(function (u) {
      var pct = _barPct(u.sessions, maxUserSessions);
      var stale = _isStale(u.lastPushAt);
      // 2026-05-18 v27: per-user AI cost + call count surfaced.
      var costStr = (u.costUSD != null && u.costUSD > 0)
        ? "$" + (u.costUSD < 0.01 ? u.costUSD.toFixed(4) : u.costUSD.toFixed(2))
        : "$0";
      var callsStr = (u.aiCalls != null && u.aiCalls > 0)
        ? u.aiCalls + " call" + (u.aiCalls === 1 ? "" : "s")
        : "no AI";
      html += '<div class="_auv_row' + (stale ? ' _auv_row_stale' : '') + '">';
      html +=   '<div class="_auv_row_top">';
      html +=     '<span class="_auv_row_label">' + _esc(_userLabel(u)) + '</span>';
      html +=     '<span class="_auv_row_meta">' +
                    u.sessions + ' session' + (u.sessions === 1 ? '' : 's') +
                    ' · ' + u.activeDays + ' day' + (u.activeDays === 1 ? '' : 's') +
                    ' · ' + costStr + ' · ' + callsStr +
                    ' · pushed ' + _fmtAgo(u.lastPushAt) +
                  '</span>';
      html +=   '</div>';
      html +=   '<div class="_auv_bar"><div class="_auv_bar_fill" style="width:' + pct.toFixed(1) + '%"></div></div>';
      html += '</div>';
    });
    html += '</div>';
  }
  html +=   '</div>';
  html += '</div>';

  // Panel 2: Most-used tools — 2026-05-18 v32: filter bar.
  // Two persisted toggles:
  //   excludeSelf  — drop the running admin's own launches from the
  //                  tally (so the admin doesn't see their own QA
  //                  clicks dominating the list).
  //   excludeAdmin — drop tools whose id starts with "admin_" or
  //                  "trophy_gallery" (chrome / dashboards, not work).
  // State lives in localStorage so refreshes preserve the choices.
  var _selfKey = "";
  try {
    if (window.eli && window.eli.tools && window.eli.tools.userIdentity) {
      var _id = window.eli.tools.userIdentity();
      var _firstInitial = _id && _id.firstName ? String(_id.firstName).charAt(0).toLowerCase() : "";
      var _full = _id && _id.name ? String(_id.name).trim() : "";
      var _parts = _full.split(/\s+/).filter(Boolean);
      var _lastInitial = _parts.length >= 2 ? _parts[_parts.length - 1].charAt(0).toLowerCase() : "";
      _selfKey = _firstInitial + (_lastInitial || "");
    }
  } catch (_) {}
  var _flt = {
    excludeSelf: window.eli && window.eli.compat && window.eli.compat.lsGet
      ? window.eli.compat.lsGet("_auv_filter_exclude_self") !== "0"  // default ON
      : true,
    excludeAdmin: window.eli && window.eli.compat && window.eli.compat.lsGet
      ? window.eli.compat.lsGet("_auv_filter_exclude_admin") !== "0" // default ON
      : true,
  };
  function _isAdminTool(toolName) {
    var n = String(toolName || "").toLowerCase();
    return n.indexOf("admin_") === 0 || n === "trophy_gallery";
  }
  function _recomputeTools() {
    var tally = {};
    (data.users || []).forEach(function (u) {
      if (_flt.excludeSelf && _selfKey && u.userKey === _selfKey) return;
      (u.days || []).forEach(function (d) {
        var tu = (d && d.toolsUsed) || {};
        Object.keys(tu).forEach(function (t) {
          if (_flt.excludeAdmin && _isAdminTool(t)) return;
          tally[t] = (tally[t] || 0) + (Number(tu[t]) || 0);
        });
      });
    });
    return Object.keys(tally).map(function (t) {
      return { tool: t, launches: tally[t] };
    }).sort(function (a, b) { return b.launches - a.launches; });
  }
  var filteredTools = _recomputeTools();
  var filteredMax = (filteredTools[0] && filteredTools[0].launches) || 0;
  html += '<div class="_auv_card">';
  html +=   '<div class="_auv_card_head"><span class="_auv_card_title">🔧 Most-Used Tools</span>' +
              '<span style="font-size:10.5px;font-weight:600;color:#475569;display:inline-flex;gap:10px;align-items:center;">' +
                '<label style="display:inline-flex;gap:4px;align-items:center;cursor:pointer;">' +
                  '<input type="checkbox" id="auvFltSelf"' + (_flt.excludeSelf ? ' checked' : '') + (_selfKey ? '' : ' disabled') + ' style="margin:0;cursor:pointer;">' +
                  '<span>Exclude self' + (_selfKey ? ' (' + _selfKey.toUpperCase() + ')' : '') + '</span>' +
                '</label>' +
                '<label style="display:inline-flex;gap:4px;align-items:center;cursor:pointer;">' +
                  '<input type="checkbox" id="auvFltAdmin"' + (_flt.excludeAdmin ? ' checked' : '') + ' style="margin:0;cursor:pointer;">' +
                  '<span>Exclude admin/system tools</span>' +
                '</label>' +
              '</span></div>';
  html +=   '<div class="_auv_card_body">';
  if (!filteredTools.length) {
    html += '<div class="_auv_empty_inner">No tool launches matching the filters.</div>';
  } else {
    html += '<div class="_auv_list" id="auvToolsList">';
    filteredTools.forEach(function (t) {
      var pct = _barPct(t.launches, filteredMax);
      html += '<div class="_auv_row">';
      html +=   '<div class="_auv_row_top">';
      html +=     '<span class="_auv_row_label">' + _esc(_fmtTool(t.tool)) + '</span>';
      html +=     '<span class="_auv_row_meta">' + t.launches + '</span>';
      html +=   '</div>';
      html +=   '<div class="_auv_bar"><div class="_auv_bar_fill" style="width:' + pct.toFixed(1) + '%"></div></div>';
      html += '</div>';
    });
    html += '</div>';
  }
  html +=   '</div>';
  html += '</div>';

  // Panel 3: Daily activity (last 7 days)
  html += '<div class="_auv_card">';
  html +=   '<div class="_auv_card_head"><span class="_auv_card_title">📅 Daily Activity — Last 7 Days</span></div>';
  html +=   '<div class="_auv_card_body">';
  if (!data.daily.length) {
    html += '<div class="_auv_empty_inner">No daily data.</div>';
  } else {
    html += '<div class="_auv_daily">';
    data.daily.forEach(function (d) {
      var pct = _barPct(d.sessions, maxDaily);
      // 2026-05-18 v27: per-day AI cost under the session count.
      var dayCost = Number(d.costUSD || 0);
      var dayCostStr = dayCost > 0
        ? (dayCost < 0.01 ? "$" + dayCost.toFixed(4) : "$" + dayCost.toFixed(2))
        : "";
      html += '<div class="_auv_daily_col">';
      html +=   '<div class="_auv_daily_bar_wrap"><div class="_auv_daily_bar" style="height:' + Math.max(2, pct).toFixed(1) + '%"></div></div>';
      html +=   '<div class="_auv_daily_count">' + d.sessions + '</div>';
      if (dayCostStr) {
        html += '<div class="_auv_daily_cost" style="font-size:9.5px;color:#0d9488;font-weight:700;margin-top:1px;">' + dayCostStr + '</div>';
      }
      html +=   '<div class="_auv_daily_date">' + _esc(_fmtDateShort(d.date)) + '</div>';
      html += '</div>';
    });
    html += '</div>';
  }
  html +=   '</div>';
  html += '</div>';

  // Panel 3.5: Per-user breakdown — each user expandable with per-day
  // (launches + cost) and per-tool (launches) detail. Added 2026-05-18
  // v28 per user request: "how much each user spent per day and per
  // tool". Cost-per-tool isn't tracked at the telemetry layer (tokens
  // only carry model, not tool), so per-tool shows launch counts.
  html += '<div class="_auv_card">';
  html +=   '<div class="_auv_card_head"><span class="_auv_card_title">👤 Per-User Breakdown</span></div>';
  html +=   '<div class="_auv_card_body">';
  if (!data.users.length) {
    html += '<div class="_auv_empty_inner">No users yet.</div>';
  } else {
    data.users.forEach(function (u, ui) {
      var totalLaunches = (u.days || []).reduce(function (a, d) {
        var dt = d && d.toolsUsed ? d.toolsUsed : {};
        return a + Object.keys(dt).reduce(function (n, k) { return n + (Number(dt[k]) || 0); }, 0);
      }, 0);
      var userCostStr = (u.costUSD != null && u.costUSD > 0)
        ? (u.costUSD < 0.01 ? "$" + u.costUSD.toFixed(4) : "$" + u.costUSD.toFixed(2))
        : "$0";
      html += '<details class="_auv_user_details" style="margin-bottom:8px;border:1px solid #e2e8f0;background:#fff;">';
      html +=   '<summary style="padding:10px 14px;cursor:pointer;display:flex;align-items:center;gap:10px;list-style:none;">';
      html +=     '<span style="font-weight:800;color:#0f172a;font-size:13px;">' + _esc(_userLabel(u)) + '</span>';
      html +=     '<span style="font-size:11px;color:#64748b;flex:1;">' +
                    totalLaunches + ' launch' + (totalLaunches === 1 ? '' : 'es') +
                    ' · ' + (u.activeDays || 0) + ' day' + ((u.activeDays || 0) === 1 ? '' : 's') +
                    ' · ' + userCostStr + ' AI spend' +
                  '</span>';
      html +=     '<span style="font-size:10px;color:#94a3b8;">▸</span>';
      html +=   '</summary>';
      html +=   '<div style="padding:8px 14px 14px 14px;background:#f8fafc;">';
      // 2026-05-18 v29: replaced the separate "per-day totals" and
      // "per-tool totals" tables with a per-day TIMELINE that shows
      // exactly WHICH tools were used on each day. Date heading +
      // sub-rows for each tool launched that day. Days most-recent
      // first. Per-day cost shown next to the date so the user sees
      // both "what" and "what it cost" at the same scan.
      var sortedDays = (u.days || []).slice().sort(function (a, b) {
        return String(b.date || "").localeCompare(String(a.date || ""));
      });
      if (sortedDays.length) {
        html += '<div style="font-size:9.5px;font-weight:800;color:#475569;text-transform:uppercase;letter-spacing:0.1em;margin-bottom:6px;">Activity Timeline</div>';
        // 2026-05-18 v32: per-tool cost from tokensByTool (v61 of
        // eli_telemetry). Inline price table — bundler isolates each
        // top-level fn so we can't call engine.etEstimateCost from
        // here. Matches the etPriceTable shape ($ per 1M tokens).
        var _PRICES = {
          "gemini-3.1-flash-lite-preview": { in: 0.04, out: 0.20 },
          "gemini-3.1-flash":               { in: 0.075, out: 0.30 },
          "gemini-2.5-flash":               { in: 0.075, out: 0.30 },
          "gemini-2.5-flash-lite-preview":  { in: 0.04, out: 0.20 },
          "gemini-2.5-pro":                 { in: 1.25, out: 5.00 },
          "gemini-1.5-pro":                 { in: 1.25, out: 5.00 },
          "gemini-1.5-flash":               { in: 0.075, out: 0.30 },
          "_default":                       { in: 0.075, out: 0.30 },
        };
        function _costForTokens(tokensMap) {
          if (!tokensMap || typeof tokensMap !== "object") return 0;
          var total = 0;
          Object.keys(tokensMap).forEach(function (model) {
            var t = tokensMap[model] || {};
            var price = _PRICES[model] || _PRICES._default;
            var inTok = Number(t.promptTokens) || 0;
            var outTok = Number(t.candidatesTokens) || 0;
            total += (inTok * price.in + outTok * price.out) / 1000000;
          });
          return total;
        }
        function _fmtCostShort(usd) {
          if (!usd || usd <= 0) return "";
          return usd < 0.0001 ? "<$0.0001" : (usd < 0.01 ? "$" + usd.toFixed(4) : "$" + usd.toFixed(2));
        }
        sortedDays.forEach(function (d) {
          var dt = d && d.toolsUsed ? d.toolsUsed : {};
          var tbt = d && d.tokensByTool ? d.tokensByTool : {};
          // Union of tool names from toolsUsed AND tokensByTool — a
          // tool may have fired AI calls but no launch (programmatic
          // helpers) or vice versa.
          var toolNames = {};
          Object.keys(dt).forEach(function (k) { toolNames[k] = true; });
          Object.keys(tbt).forEach(function (k) { if (k !== "_unknown") toolNames[k] = true; });
          var toolEntries = Object.keys(toolNames).map(function (t) {
            return {
              tool: t,
              count: Number(dt[t]) || 0,
              cost: _costForTokens(tbt[t] || {}),
            };
          }).sort(function (a, b) {
            // Sort by cost desc when costs differ, else by count desc.
            if (Math.abs(a.cost - b.cost) > 1e-6) return b.cost - a.cost;
            return b.count - a.count;
          });
          if (!toolEntries.length) return;
          var dl = toolEntries.reduce(function (n, e) { return n + e.count; }, 0);
          var dc = Number(d.estCostUSD || 0);
          // If estCostUSD is 0 but tokensByTool has data (pre-cost-
          // stamp), sum it ourselves.
          if (!dc) dc = toolEntries.reduce(function (s, e) { return s + (e.cost || 0); }, 0);
          var dcStr = _fmtCostShort(dc);
          // Date heading row
          html += '<div style="margin-top:8px;padding:6px 10px;background:#1e293b;color:#fff;display:flex;justify-content:space-between;align-items:center;font-size:11px;">' +
                    '<span style="font-weight:800;">' + _esc(_fmtDateShort(d.date)) + '</span>' +
                    '<span style="font-size:10.5px;opacity:0.85;">' +
                      dl + ' launch' + (dl === 1 ? '' : 'es') +
                      (dcStr ? ' · <span style="color:#5eead4;font-weight:700;">' + dcStr + '</span>' : '') +
                    '</span>' +
                  '</div>';
          // Tool rows for this date — three columns: tool | launches | cost.
          html += '<div style="border:1px solid #e2e8f0;border-top:none;background:#fff;">';
          toolEntries.forEach(function (e, ti) {
            var sep = ti < toolEntries.length - 1 ? 'border-bottom:1px solid #f1f5f9;' : '';
            var costStr = _fmtCostShort(e.cost);
            html += '<div style="display:grid;grid-template-columns:1fr 60px 80px;align-items:center;padding:5px 12px;gap:8px;' + sep + 'font-size:11.5px;">' +
                      '<span style="color:#334155;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;" title="' + _esc(_fmtTool(e.tool)) + '">' + _esc(_fmtTool(e.tool)) + '</span>' +
                      '<span style="color:#0f172a;font-weight:700;text-align:right;">' + e.count + '</span>' +
                      '<span style="color:' + (e.cost > 0 ? '#0d9488' : '#94a3b8') + ';font-weight:' + (e.cost > 0 ? '700' : '500') + ';text-align:right;font-family:ui-monospace,monospace;font-size:10.5px;">' + (costStr || '—') + '</span>' +
                    '</div>';
          });
          // If there's _unknown bucket cost (AI fired before any
          // tool launch), surface it as a separate row at the bottom
          // so the user knows there's unattributed spend.
          var unknownCost = _costForTokens(tbt._unknown || {});
          if (unknownCost > 0) {
            html += '<div style="display:grid;grid-template-columns:1fr 60px 80px;align-items:center;padding:5px 12px;border-top:1px dashed #cbd5e1;gap:8px;font-size:11px;color:#94a3b8;font-style:italic;">' +
                      '<span>unattributed (no active tool)</span>' +
                      '<span style="text-align:right;">—</span>' +
                      '<span style="text-align:right;font-family:ui-monospace,monospace;">' + _fmtCostShort(unknownCost) + '</span>' +
                    '</div>';
          }
          html += '</div>';
        });
      }
      if (u.aiCalls > 0) {
        html += '<div style="margin-top:12px;font-size:10.5px;color:#64748b;padding:6px 10px;background:#fff;border:1px solid #e2e8f0;">' +
                  '<strong style="color:#0d9488;">AI usage:</strong> ' +
                  u.aiCalls + ' call' + (u.aiCalls === 1 ? '' : 's') +
                  ' · ' + (u.promptTokens || 0).toLocaleString() + ' prompt + ' +
                  (u.candidatesTokens || 0).toLocaleString() + ' response tokens' +
                '</div>';
      }
      html +=   '</div>';
      html += '</details>';
    });
  }
  html +=   '</div>';
  html += '</div>';

  // Panel 4: Per-user × per-day grid (collapsible)
  html += '<div class="_auv_card">';
  html +=   '<div class="_auv_card_head _auv_grid_head" id="auvGridHead">';
  html +=     '<span class="_auv_card_title">📐 Per-User × Per-Day Grid</span>';
  html +=     '<span class="_auv_grid_toggle" id="auvGridToggle">▸ Expand</span>';
  html +=   '</div>';
  html +=   '<div class="_auv_card_body _auv_grid_body" id="auvGridBody" style="display:none">';
  if (!data.grid.users.length || !data.grid.dates.length) {
    html += '<div class="_auv_empty_inner">Not enough data for grid view.</div>';
  } else {
    html += '<div class="_auv_grid_scroll"><table class="_auv_grid_tbl">';
    html += '<thead><tr><th class="_auv_grid_user_col">User</th>';
    data.grid.dates.forEach(function (date) {
      html += '<th>' + _esc(_fmtDateShort(date)) + '</th>';
    });
    html += '</tr></thead><tbody>';
    data.grid.users.forEach(function (u) {
      html += '<tr><td class="_auv_grid_user_col">' + _esc(_userLabel(u)) + '</td>';
      data.grid.dates.forEach(function (date) {
        var cell = u.cells[date];
        if (!cell || !cell.sessions) {
          html += '<td class="_auv_grid_cell _auv_grid_cell_empty">·</td>';
        } else {
          var top = cell.topTool ? _fmtTool(cell.topTool) : "—";
          html += '<td class="_auv_grid_cell" title="' + _esc(top) + ' · ' + cell.topCount + ' launch' + (cell.topCount === 1 ? '' : 'es') + '">';
          html +=   '<div class="_auv_grid_sessions">' + cell.sessions + '</div>';
          html +=   '<div class="_auv_grid_toptool">' + _esc(top) + '</div>';
          html += '</td>';
        }
      });
      html += '</tr>';
    });
    html += '</tbody></table></div>';
  }
  html +=   '</div>';
  html += '</div>';

  html += '<div class="_auv_footer">' +
    'Stale rows (dimmed) haven\'t pushed in 3+ days. Cache: 5 minutes.' +
    '</div>';
  html += '</div>'; // _auv_root

  host.innerHTML = html;

  // Wire handlers (idempotent — caller re-renders on refresh).
  var refreshEl = host.querySelector("#auvRefresh");
  if (refreshEl && onRefresh) refreshEl.onclick = onRefresh;
  var exportEl = host.querySelector("#auvExport");
  if (exportEl && onExport) exportEl.onclick = onExport;
  var toggleEl = host.querySelector("#auvToggleNames");
  if (toggleEl && onToggleNames && hasLookup) {
    toggleEl.onclick = function () { onToggleNames(!showResolvedNames); };
  }
  // 2026-05-18 v32: filter toggles persist to localStorage and trigger
  // a full re-render via onRefresh (cache stays — only the rendered
  // aggregate changes).
  var fltSelf = host.querySelector("#auvFltSelf");
  var fltAdmin = host.querySelector("#auvFltAdmin");
  function _persistFilter(key, on) {
    try {
      if (window.eli && window.eli.compat && window.eli.compat.lsSet) {
        window.eli.compat.lsSet(key, on ? "1" : "0");
      }
    } catch (_) {}
  }
  if (fltSelf && onRefresh) {
    fltSelf.onchange = function () {
      _persistFilter("_auv_filter_exclude_self", fltSelf.checked);
      onRefresh();
    };
  }
  if (fltAdmin && onRefresh) {
    fltAdmin.onchange = function () {
      _persistFilter("_auv_filter_exclude_admin", fltAdmin.checked);
      onRefresh();
    };
  }
  var gridHead = host.querySelector("#auvGridHead");
  var gridBody = host.querySelector("#auvGridBody");
  var gridToggle = host.querySelector("#auvGridToggle");
  if (gridHead && gridBody && gridToggle) {
    gridHead.style.cursor = "pointer";
    gridHead.onclick = function () {
      var open = gridBody.style.display !== "none";
      gridBody.style.display = open ? "none" : "";
      gridToggle.textContent = open ? "▸ Expand" : "▾ Collapse";
    };
  }
}

jsonTools.init:
function init(eli) {
  if (!eli || !eli.tools) return;
  var bundle = eli.tools._loaded && eli.tools._loaded.admin_usage_viewer;
  if (!bundle) return;
  var efns = bundle._eliEngineFns || {};
  var vfns = bundle._eliViewFns || {};
  var auvListUsageFiles = efns.auvListUsageFiles;
  var auvFetchDigest    = efns.auvFetchDigest;
  var auvAggregate      = efns.auvAggregate;
  var auvBuildCsv       = efns.auvBuildCsv;
  var renderDashboard   = vfns.renderDashboard;
  if (!auvListUsageFiles || !auvAggregate || !renderDashboard) {
    eli.log.event("tool", "admin_usage_viewer_load_failed", {
      hasList: !!auvListUsageFiles, hasAgg: !!auvAggregate, hasView: !!renderDashboard,
    });
    return;
  }

  var CACHE_KEY = "_admin_usage_cache";
  var CACHE_AT_KEY = "_admin_usage_cache_at";
  var CACHE_TTL_MS = 5 * 60 * 1000;

  // 2026-05-23 (Phase 2): self-loading identity lookup. Removes the
  // order-dependency where admin had to open admin_fleet FIRST to populate
  // window._eli3_admin_fleet_lookup before opening admin_usage_viewer.
  // Loads the same encrypted file admin_fleet uses (fleet-identity.enc.json)
  // and decrypts via the kernel's _eliDecryptFromRepo helper using the
  // eli_admin_password localStorage value. Cached in module scope.
  var GH_OWNER = "apndrewn";
  var GH_REPO = "eli-data";
  var GH_BRANCH = "main";
  var IDENTITY_PATH = "fleet-identity.enc.json";
  var _identityLookup = null;
  var _identityLoadPromise = null;
  var _identityLoadError = null;
  function _b64ToStr(b) {
    try {
      var bytes = Uint8Array.from(atob(String(b).replace(/\s/g, "")), function (c) { return c.charCodeAt(0); });
      return new TextDecoder().decode(bytes);
    } catch (e) { return ""; }
  }
  function _ensureIdentityLookup() {
    // Already loaded — return cached.
    if (_identityLookup) return Promise.resolve(_identityLookup);
    // Inflight — share the promise.
    if (_identityLoadPromise) return _identityLoadPromise;
    // Prefer admin_fleet's shared global if it's already populated
    // (avoids a redundant fetch when admin opened admin_fleet first).
    var shared = window._eli3_admin_fleet_lookup;
    if (shared && Object.keys(shared).length) {
      _identityLookup = shared;
      return Promise.resolve(_identityLookup);
    }
    var pat = eli.compat.lsGet("eli_user_github_pat");
    var password = eli.compat.lsGet("eli_admin_password");
    if (!pat || !password) {
      _identityLoadError = !password
        ? "Admin password missing — set eli_admin_password"
        : "GitHub PAT missing — set eli_user_github_pat";
      return Promise.resolve(null);
    }
    var url = "https://api.github.com/repos/" + GH_OWNER + "/" + GH_REPO +
      "/contents/" + encodeURIComponent(IDENTITY_PATH) +
      "?ref=" + encodeURIComponent(GH_BRANCH) + "&t=" + Date.now();
    _identityLoadPromise = fetch(url, {
      cache: "no-store",
      headers: {
        "Authorization": "Bearer " + pat,
        "Accept": "application/vnd.github+json",
        "X-GitHub-Api-Version": "2022-11-28",
      },
    }).then(function (r) {
      if (r.status === 404) { _identityLoadError = "Identity file not on CDN"; return null; }
      if (!r.ok) { _identityLoadError = "Identity fetch failed: HTTP " + r.status; return null; }
      return r.json();
    }).then(function (j) {
      if (!j || !j.content) return null;
      var content = _b64ToStr(j.content);
      var blob;
      try { blob = JSON.parse(content); }
      catch (e) { _identityLoadError = "Identity file is not valid JSON"; return null; }
      if (window._eliIsEncryptedBlob && !window._eliIsEncryptedBlob(blob)) {
        // Plain (back-compat or pre-encryption) — accept it.
        _identityLookup = blob.identities || blob || {};
        try { window._eli3_admin_fleet_lookup = _identityLookup; } catch (_) {}
        return _identityLookup;
      }
      if (!window._eliDecryptFromRepo) {
        _identityLoadError = "Kernel decrypt helper missing — reload";
        return null;
      }
      return window._eliDecryptFromRepo(password, blob).then(function (decrypted) {
        _identityLookup = (decrypted && decrypted.identities) || {};
        try { window._eli3_admin_fleet_lookup = _identityLookup; } catch (_) {}
        return _identityLookup;
      }).catch(function (err) {
        _identityLoadError = "Decrypt failed: " + (err && err.message || err);
        return null;
      });
    }).catch(function (err) {
      _identityLoadError = "Identity fetch error: " + (err && err.message || err);
      return null;
    }).then(function (result) {
      _identityLoadPromise = null; // allow retry on next call if it failed
      return result;
    });
    return _identityLoadPromise;
  }

  function _readCache() {
    try {
      var s = eli.compat.lsGet(CACHE_KEY);
      var at = Number(eli.compat.lsGet(CACHE_AT_KEY) || 0);
      if (!s || !at) return null;
      if ((Date.now() - at) > CACHE_TTL_MS) return null;
      return { digests: JSON.parse(s), cachedAt: at };
    } catch (e) { return null; }
  }
  function _writeCache(digests) {
    try {
      eli.compat.lsSet(CACHE_KEY, JSON.stringify(digests));
      eli.compat.lsSet(CACHE_AT_KEY, String(Date.now()));
    } catch (e) {
      // Quota — drop the cache rather than crash. Refresh just re-fetches.
      try { eli.compat.lsRemove(CACHE_KEY); eli.compat.lsRemove(CACHE_AT_KEY); } catch (_) {}
    }
  }

  // Fetch all usage digests. force=true bypasses cache.
  function _fetchAll(opts) {
    opts = opts || {};
    if (!opts.force) {
      var cached = _readCache();
      if (cached) return Promise.resolve(cached);
    }
    return auvListUsageFiles().then(function (files) {
      if (!files.length) {
        _writeCache([]);
        return { digests: [], cachedAt: Date.now() };
      }
      return Promise.all(files.map(function (f) {
        return auvFetchDigest(f.download_url);
      })).then(function (digests) {
        var clean = digests.filter(Boolean);
        _writeCache(clean);
        return { digests: clean, cachedAt: Date.now() };
      });
    }).catch(function (err) {
      eli.log.event("admin_usage_viewer", "fetch_failed", { msg: err && err.message });
      return { digests: [], cachedAt: 0 };
    });
  }

  function _downloadCsv(csvText) {
    try {
      var blob = new Blob([csvText], { type: "text/csv;charset=utf-8" });
      var url = URL.createObjectURL(blob);
      var a = document.createElement("a");
      a.href = url;
      a.download = "eli-usage-" + new Date().toISOString().slice(0, 10) + ".csv";
      document.body.appendChild(a);
      a.click();
      setTimeout(function () {
        try { document.body.removeChild(a); } catch (e) {}
        try { URL.revokeObjectURL(url); } catch (e) {}
      }, 100);
    } catch (e) {
      if (typeof showToast === "function") showToast("CSV export failed: " + (e.message || "unknown"), "err");
    }
  }

  // 2026-05-23 (Phase 2): build an initials/UUID → displayName resolver
  // from the identity lookup (loaded via _ensureIdentityLookup before
  // paint, or from admin_fleet's shared global). Returns a function
  // ((userKey, userId) → displayName | null) so the view can flip on/off
  // via toggle without reaggregating. Falls back to a no-op when no
  // lookup is loaded (e.g. admin_password missing).
  function _buildNameResolver() {
    var lookup = _identityLookup || (window._eli3_admin_fleet_lookup) || {};
    var keys = Object.keys(lookup);
    if (!keys.length) return null;
    // Index by userId for direct hits, and by initials for fallback
    // disambiguation. Initials index value is an ARRAY because multiple
    // users can share initials — caller decides what to do (display all,
    // pick first, leave unresolved).
    var byUserId = {};
    var byInitials = {};
    function _initials(rec) {
      var first = String(rec.firstName || rec.name || "").trim().toLowerCase().replace(/[^a-z0-9]/g, "");
      var nm = String(rec.name || (rec.firstName + " " + (rec.lastName || ""))).trim();
      var parts = nm.split(/\s+/).filter(Boolean);
      var fi = first.charAt(0);
      var li = "";
      if (parts.length >= 2) {
        var last = parts[parts.length - 1].toLowerCase().replace(/[^a-z0-9]/g, "");
        if (last) li = last.charAt(0);
      }
      return li ? fi + li : fi;
    }
    function _display(rec) {
      if (rec.firstName && rec.lastName) return rec.firstName + " " + rec.lastName;
      if (rec.name) return rec.name;
      if (rec.email) return rec.email;
      return null;
    }
    keys.forEach(function (uid) {
      var rec = lookup[uid] || {};
      byUserId[uid] = _display(rec);
      var ini = _initials(rec);
      if (ini) {
        byInitials[ini] = byInitials[ini] || [];
        byInitials[ini].push({ userId: uid, display: byUserId[uid] });
      }
    });
    return function (userKey, userId) {
      // Best path: digest carries userId from fleet block.
      if (userId && byUserId[userId]) return byUserId[userId];
      // Fallback: resolve via initials. Only if uniquely matched —
      // otherwise the caller can't know which "AN" the row belongs to.
      var ini = String(userKey || "").toLowerCase();
      var hits = byInitials[ini];
      if (hits && hits.length === 1) return hits[0].display;
      return null;
    };
  }

  // 2026-05-23 (Phase 2): persist the toggle state across renders.
  var SHOW_NAMES_KEY = "_admin_usage_show_resolved_names";
  function _readShowNames() {
    try {
      var v = eli.compat.lsGet(SHOW_NAMES_KEY);
      return v == null ? true : v === "1"; // default ON
    } catch (_) { return true; }
  }
  function _writeShowNames(on) {
    try { eli.compat.lsSet(SHOW_NAMES_KEY, on ? "1" : "0"); } catch (_) {}
  }

  function _paint(host, result) {
    var aggregated = auvAggregate(result.digests || []);
    var resolveName = _buildNameResolver();
    var hasLookup = !!resolveName;
    renderDashboard({
      host: host,
      data: aggregated,
      totalDigests: (result.digests || []).length,
      cachedAt: result.cachedAt,
      // 2026-05-23 (Phase 2): name resolution wiring.
      resolveName: resolveName,
      showResolvedNames: _readShowNames(),
      hasLookup: hasLookup,
      // 2026-05-23 (Phase 2): when lookup didn't load, surface WHY in
      // the toggle's title attribute. View takes lookupError as opt and
      // uses it in the disabled-button tooltip.
      lookupError: hasLookup ? null : _identityLoadError,
      onToggleNames: function (newVal) {
        _writeShowNames(newVal);
        _paint(host, result);
      },
      onRefresh: function () {
        host.innerHTML = '<div class="_auv_loading">Reloading…</div>';
        // Reset identity cache so refresh re-attempts the lookup load —
        // covers the case where admin set the password mid-session and
        // hits Refresh to pick up the resolver.
        if (!_identityLookup) {
          _identityLoadError = null;
        }
        Promise.all([
          _fetchAll({ force: true }),
          _ensureIdentityLookup(),
        ]).then(function (r) { _paint(host, r[0]); });
      },
      onExport: function () {
        var csv = auvBuildCsv(result.digests || []);
        _downloadCsv(csv);
      },
    });
  }

  function _show() {
    try { if (eli.stats && eli.stats.record) eli.stats.record("appOpenedAdminUsageViewer"); } catch (e) {}
    try { if (eli.fsm && eli.fsm.getCurrent && eli.fsm.getCurrent() === "idle") eli.fsm.transition("scanning"); } catch (e) {}
    var out = (eli.ui && typeof eli.ui.claimOutput === "function") ? eli.ui.claimOutput() : document.getElementById("output");
    if (!out) {
      if (typeof showToast === "function") showToast("Output area unavailable", "err");
      return;
    }
    out.classList.add("eli-view-enter");
    out.innerHTML = '<div class="_auv_loading">Loading usage data…</div>';
    // 2026-05-23 (Phase 2): load identity lookup IN PARALLEL with the
    // first digest fetch. Toggle becomes available on the very first
    // paint instead of requiring a Refresh after opening admin_fleet.
    Promise.all([
      _fetchAll({ force: false }),
      _ensureIdentityLookup(),
    ]).then(function (r) { _paint(out, r[0]); });
  }

  eli.register({
    tile: { app_admin_usage_viewer: _show },
    admin_usage_viewer: { open: _show },
  });

  eli.log.event("tool", "admin_usage_viewer_initialized", {});
}

