  font: 800 9px/1 Inter, sans-serif;
  letter-spacing: 1.4px;
  text-transform: uppercase;
  color: #c9a227;
  margin-bottom: 4px;
}
._auv_header_title {
  font: 800 22px/1.1 "Book Antiqua", Georgia, serif;
  margin: 0;
}
._auv_header_sub {
  font-size: 11px;
  color: rgba(255, 255, 255, 0.7);
  margin-top: 4px;
}
._auv_header_btns { display: flex; gap: 8px; }

._auv_btn {
  padding: 8px 14px;
  font: 700 10px/1 Inter, sans-serif;
  letter-spacing: 0.4px;
  text-transform: uppercase;
  border: none;
  cursor: pointer;
  transition: filter 0.15s, transform 0.05s;
}
._auv_btn:active { transform: translateY(1px); }
._auv_btn_platinum {
  background: linear-gradient(180deg, #f1f5f9 0%, #cbd5e1 100%);
  color: #0f172a;
  border: 1px solid #94a3b8;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.8),
    0 1px 2px rgba(15, 23, 42, 0.08);
}
._auv_btn_platinum:hover { filter: brightness(1.04); }

/* ─── Cards ──────────────────────────────────────────────────── */
._auv_card {
  background: #fff;
  border: 1px solid #e2e8f0;
  margin: 14px 14px 0 14px;
  padding: 0;
}
._auv_card_head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 12px 16px;
  background: linear-gradient(180deg, #fcfcfd, #f8fafc);
  border-bottom: 1px solid #f1f5f9;
}
._auv_card_title {
  font: 800 11px/1 Inter, sans-serif;
  text-transform: uppercase;
  letter-spacing: 0.6px;
  color: #0f172a;
}
._auv_card_body { padding: 14px 16px; }
._auv_empty {
  margin: 22px 14px 0 14px;
  padding: 20px 18px;
  background: #fff;
  border: 1px dashed #cbd5e1;
  font-size: 12px;
  color: #475569;
  text-align: center;
}
._auv_empty code {
  background: #f1f5f9;
  padding: 1px 5px;
  font-family: ui-monospace, "SF Mono", Consolas, monospace;
  font-size: 11px;
}
._auv_empty_inner {
  padding: 14px 0;
  text-align: center;
  font-size: 11px;
  color: #94a3b8;
}

/* ─── Rows + bars (panels 1 & 2) ─────────────────────────────── */
._auv_list { display: flex; flex-direction: column; gap: 10px; }
._auv_row { display: flex; flex-direction: column; gap: 4px; }
._auv_row_stale { opacity: 0.55; }
._auv_row_top {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 8px;
}
._auv_row_label {
  font: 700 12px Inter, sans-serif;
  color: #0f172a;
}
._auv_row_meta {
  font: 600 10px Inter, sans-serif;
  color: #64748b;
  text-align: right;
}
._auv_bar {
  height: 8px;
  background: #f1f5f9;
  border-radius: 0;
  overflow: hidden;
}
._auv_bar_fill {
  height: 100%;
  background: linear-gradient(90deg, #c9a227 0%, #e6c068 100%);
  transition: width 0.3s ease;
}

/* ─── Daily column chart (panel 3) ───────────────────────────── */
._auv_daily {
  display: flex;
  align-items: flex-end;
  gap: 6px;
  height: 140px;
  padding: 8px 0 0 0;
}
._auv_daily_col {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  min-width: 0;
}
._auv_daily_bar_wrap {
  width: 100%;
  height: 90px;
  background: #f8fafc;
  display: flex;
  align-items: flex-end;
  justify-content: center;
}
._auv_daily_bar {
  width: 70%;
  background: linear-gradient(180deg, #e6c068 0%, #c9a227 100%);
  min-height: 2px;
  transition: height 0.3s ease;
}
._auv_daily_count {
  font: 700 11px Inter, sans-serif;
  color: #0f172a;
}
._auv_daily_date {
  font: 600 9px Inter, sans-serif;
  color: #64748b;
  text-transform: uppercase;
  letter-spacing: 0.4px;
  white-space: nowrap;
}

/* ─── Grid (panel 4) ─────────────────────────────────────────── */
._auv_grid_head { cursor: pointer; }
._auv_grid_toggle {
  font: 700 10px Inter, sans-serif;
  color: #475569;
  letter-spacing: 0.4px;
}
._auv_grid_scroll {
  overflow-x: auto;
  border: 1px solid #f1f5f9;
}
._auv_grid_tbl {
  width: 100%;
  border-collapse: collapse;
  font-size: 11px;
}
._auv_grid_tbl thead th {
  background: #f8fafc;
  color: #475569;
  text-align: center;
  padding: 8px 6px;
  font: 700 10px Inter, sans-serif;
  text-transform: uppercase;
  letter-spacing: 0.4px;
  border-bottom: 1px solid #e2e8f0;
}
._auv_grid_tbl tbody td {
  padding: 6px;
  border-bottom: 1px solid #f1f5f9;
  text-align: center;
  vertical-align: middle;
}
._auv_grid_user_col {
  text-align: left !important;
  font: 700 11px Inter, sans-serif;
  color: #0f172a;
  padding-left: 10px !important;
  white-space: nowrap;
}
._auv_grid_cell_empty { color: #cbd5e1; }
._auv_grid_sessions {
  font: 700 12px Inter, sans-serif;
  color: #0f172a;
}
._auv_grid_toptool {
  font: 600 9px Inter, sans-serif;
  color: #94a3b8;
  margin-top: 2px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 80px;
}

._auv_footer {
  padding: 16px 22px 0 22px;
  font-size: 10px;
  color: #94a3b8;
  text-align: center;
  line-height: 1.5;
}
._auv_footer code {
  background: #f1f5f9;
  padding: 1px 4px;
  font-family: ui-monospace, "SF Mono", Consolas, monospace;
  font-size: 10px;
}
